
.shop-panel {
  display: flex;
  flex-direction: column;
}

.shop-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.section-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-cyan);
  letter-spacing: 1px;
}

.balance {
  display: flex;
  align-items: center;
  gap: 3px;
  font-family: var(--font-data);
  font-size: 13px;
  color: var(--accent-gold);
}

.balance-icon {
  font-size: 11px;
}

.shop-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.shop-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-left: 3px solid;
  padding: 8px 10px;
  border-radius: 3px;
  transition: all 0.2s;

  &:hover {
    background: var(--bg-card-hover);
  }
}

.shop-item-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3px;
}

.shop-item-name {
  font-size: 12px;
  font-weight: 700;
}

.quality-tag {
  font-family: var(--font-data);
  font-size: 9px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 2px;
  border: 1px solid;
}

.shop-item-desc {
  font-size: 11px;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.shop-item-footer {
  display: flex;
  align-items: center;
  gap: 8px;
}

.shop-price {
  font-family: var(--font-data);
  font-size: 11px;
  color: var(--accent-gold);

  &.insufficient {
    color: var(--accent-red);
    text-decoration: line-through;
  }
}

.shop-stock {
  font-size: 10px;
  color: var(--text-dim);
  flex: 1;
}

.buy-btn {
  font-family: var(--font-hud);
  font-size: 10px;
  font-weight: 600;
  padding: 3px 10px;
  background: rgba(6, 182, 212, 0.1);
  border: 1px solid var(--accent-cyan);
  color: var(--accent-cyan);
  border-radius: 2px;
  cursor: pointer;
  transition: all 0.2s;

  &:hover:not(:disabled) {
    background: rgba(6, 182, 212, 0.2);
    box-shadow: var(--glow-cyan);
  }

  &:disabled {
    opacity: 0.3;
    cursor: not-allowed;
  }

  &:active:not(:disabled) {
    transform: scale(0.95);
  }
}

.empty-hint {
  text-align: center;
  color: var(--text-dim);
  font-size: 11px;
  padding: 16px;
  font-style: italic;
}

