
.hud-container {
  width: 100%;
  max-width: 720px;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  box-shadow:
    var(--glow-cyan),
    inset 0 1px 0 rgba(6, 182, 212, 0.05);
  display: flex;
  flex-direction: column;
  font-family: var(--font-hud);
  color: var(--text-primary);
  margin: 0 auto;
  position: relative;
  overflow: hidden;

  // 顶部扫描线装饰
  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--accent-cyan), transparent);
  }
}

.content-area {
  padding: 10px 12px;
  min-height: 100px;
}

// 淡入动画
.fade-enter-active,
.fade-leave-active {
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}
.fade-enter-from {
  opacity: 0;
  transform: translateY(6px);
}
.fade-leave-to {
  opacity: 0;
  transform: translateY(-6px);
}
