
.world-header {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(6, 182, 212, 0.05) 0%, transparent 100%);
}

.header-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.dungeon-info {
  display: flex;
  align-items: center;
  gap: 6px;
}

.dungeon-label {
  font-family: var(--font-data);
  font-size: 9px;
  color: var(--accent-cyan);
  letter-spacing: 2px;
  opacity: 0.7;
}

.dungeon-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.difficulty-badge {
  font-family: var(--font-data);
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 2px;
  border: 1px solid;
}

.survivors {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--text-secondary);
}

.survivor-count {
  font-family: var(--font-data);
  color: var(--accent-amber);
}

.header-meta {
  display: flex;
  gap: 16px;
  margin-bottom: 6px;
}

.meta-item {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-secondary);
}

.meta-icon {
  color: var(--accent-cyan);
  font-size: 10px;
}

.progress-line {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
}

.progress-label {
  font-family: var(--font-data);
  font-size: 9px;
  color: var(--accent-cyan);
  letter-spacing: 1px;
  flex-shrink: 0;
}

.progress-text {
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rule-section {
  margin-top: 6px;
}

.rule-toggle {
  font-size: 11px;
  color: var(--accent-cyan);
  cursor: pointer;
  user-select: none;
  opacity: 0.8;
  transition: opacity 0.2s;
  &:hover {
    opacity: 1;
  }
}

.rule-content {
  margin-top: 4px;
  padding: 6px 8px;
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: 3px;

  pre {
    font-size: 11px;
    color: var(--text-secondary);
    white-space: pre-wrap;
    word-break: break-all;
    font-family: var(--font-hud);
    line-height: 1.5;
  }
}

