
.team-panel {
  display: flex;
  flex-direction: column;
}

.section-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-cyan);
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.team-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

// ========== 队友卡片 ==========
.mate-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 10px;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    background: var(--bg-card-hover);
    border-color: rgba(6, 182, 212, 0.3);
  }

  &.expanded {
    border-color: var(--accent-cyan);
    box-shadow: 0 0 8px rgba(6, 182, 212, 0.15);
  }
}

// ========== 头部 ==========
.mate-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.mate-identity {
  display: flex;
  align-items: center;
  gap: 6px;
}

.mate-name {
  font-size: 13px;
  font-weight: 700;
}

.mate-job {
  font-size: 10px;
  color: var(--accent-cyan);
  background: rgba(6, 182, 212, 0.1);
  border: 1px solid rgba(6, 182, 212, 0.2);
  padding: 1px 6px;
  border-radius: 2px;
}

.mate-level {
  font-family: var(--font-data);
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-amber);
}

// ========== HP 条 ==========
.hp-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}

.hp-label {
  font-size: 10px;
  color: var(--text-dim);
  width: 24px;
  font-family: var(--font-data);
  font-weight: 600;
}

.hp-track {
  flex: 1;
  height: 5px;
  background: rgba(30, 58, 95, 0.3);
  border-radius: 3px;
  overflow: hidden;
}

.hp-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.5s ease;

  &.hp-good {
    background: linear-gradient(90deg, var(--accent-green), #34d399);
  }
  &.hp-warn {
    background: linear-gradient(90deg, var(--accent-amber), #fbbf24);
  }
  &.hp-danger {
    background: linear-gradient(90deg, var(--accent-red), #f87171);
    animation: pulse-bar 1.5s ease-in-out infinite;
  }
}

.hp-value {
  font-family: var(--font-data);
  font-size: 10px;
  color: var(--text-secondary);
  min-width: 48px;
  text-align: right;
}

// ========== 好感度条 ==========
.favor-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}

.favor-label {
  font-size: 10px;
  color: var(--text-dim);
  width: 24px;
}

.favor-track {
  flex: 1;
  height: 5px;
  background: rgba(30, 58, 95, 0.3);
  border-radius: 3px;
  overflow: hidden;
}

.favor-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-cyan), var(--accent-blue));
  border-radius: 3px;
  transition: width 0.5s ease;

  &.high {
    background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));
  }
  &.low {
    background: linear-gradient(90deg, var(--accent-red), var(--accent-amber));
  }
}

.favor-value {
  font-family: var(--font-data);
  font-size: 10px;
  color: var(--text-secondary);
  min-width: 24px;
  text-align: right;
}

// ========== 状态 ==========
.mate-status {
  font-size: 11px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 3px;
}

.status-dot {
  font-size: 8px;
  &.good {
    color: var(--accent-green);
  }
  &.warn {
    color: var(--accent-amber);
  }
  &.danger {
    color: var(--accent-red);
  }
  &.neutral {
    color: var(--text-dim);
  }
}

.expand-hint {
  margin-left: auto;
  font-size: 9px;
  color: var(--text-dim);
  transition: color 0.2s;
}

.mate-card:hover .expand-hint {
  color: var(--accent-cyan);
}

// ========== 展开详情 ==========
.mate-details {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
  cursor: default;
}

.detail-section {
  margin-bottom: 10px;

  &:last-child {
    margin-bottom: 0;
  }
}

.detail-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-cyan);
  margin-bottom: 6px;
  opacity: 0.8;
}

// --- 属性迷你条 ---
.attr-mini-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 4px;
}

.attr-mini-row {
  display: flex;
  align-items: center;
  gap: 3px;
}

.attr-mini-icon {
  font-size: 10px;
  width: 14px;
  text-align: center;
}

.attr-mini-name {
  font-size: 10px;
  color: var(--text-dim);
  width: 20px;
}

.attr-mini-track {
  flex: 1;
  height: 4px;
  background: rgba(30, 58, 95, 0.3);
  border-radius: 2px;
  overflow: hidden;
}

.attr-mini-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-cyan));
  border-radius: 2px;
  transition: width 0.3s ease;
}

.attr-mini-val {
  font-family: var(--font-data);
  font-size: 10px;
  color: var(--text-primary);
  width: 22px;
  text-align: right;
  font-weight: 600;
}

// --- 技能迷你列表 ---
.skill-mini-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.skill-mini-card {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-left: 3px solid;
  padding: 5px 8px;
  border-radius: 3px;
}

.skill-mini-header {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 2px;
}

.skill-mini-name {
  font-size: 11px;
  font-weight: 700;
  flex: 1;
}

.skill-mini-type {
  font-size: 9px;
  color: var(--text-dim);
  padding: 0 4px;
  border: 1px solid var(--border);
  border-radius: 2px;
}

.skill-mini-desc {
  font-size: 10px;
  color: var(--text-dim);
}

// --- 装备迷你格 ---
.equip-mini-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
}

.equip-mini-item {
  display: flex;
  align-items: center;
  gap: 3px;
  background: var(--bg-panel);
  border: 1px solid var(--border);
  padding: 4px 6px;
  border-radius: 2px;
  border-left: 2px solid var(--border);

  &.empty {
    opacity: 0.45;
  }
}

.equip-mini-slot {
  font-size: 10px;
}

.equip-mini-name {
  font-size: 10px;
  font-weight: 600;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  &.empty-name {
    color: var(--text-dim);
    font-weight: 400;
    font-style: italic;
  }
}

.equip-mini-quality {
  font-family: var(--font-data);
  font-size: 8px;
  font-weight: 700;
  flex-shrink: 0;
}

// ========== 主角评价 ==========
.mate-comment {
  font-size: 10px;
  color: var(--text-dim);
  font-style: italic;
  margin-top: 4px;
}

// ========== 空提示 ==========
.empty-hint {
  text-align: center;
  color: var(--text-dim);
  font-size: 11px;
  padding: 16px;
  font-style: italic;
}

// ========== 展开动画 ==========
.slide-enter-active,
.slide-leave-active {
  transition: all 0.25s ease;
  overflow: hidden;
}
.slide-enter-from,
.slide-leave-to {
  opacity: 0;
  max-height: 0;
}
.slide-enter-to,
.slide-leave-from {
  opacity: 1;
  max-height: 600px;
}

// ========== HP 危险脉冲 ==========
@keyframes pulse-bar {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

